macdState = ta.crossover(macdLine, signalLine) ? "bullish_cross" : ta.crossunder(macdLine, signalLine) ? "bearish_cross" : "neutral"

// --- UT BOT TRIGGER (FAST OSCILLATOR CROSS) ---
